def experiment(inputs):
    import random
    import statistics
    def run_agent(seed):
        random.seed(seed)
        state = 0.5
        for _ in range(100):
            noise = random.uniform(-0.05, 0.05)
            state = max(0.0, min(1.0, state + noise))
        return state
    agent_states = [run_agent(inputs['seeds'][i % len(inputs['seeds'])]) for i in range(50)]
    variance = statistics.variance(agent_states)
    return {'divergence_variance': variance}
